package jp.wakeguard.alarm;
import android.appwidget.*;import android.content.*;import android.os.SystemClock;import android.widget.RemoteViews;
public class StopwatchWidgetProvider extends AppWidgetProvider{
 static void update(Context c,AppWidgetManager m,int id){RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.widget_stopwatch);android.content.SharedPreferences p=c.getSharedPreferences("clock_tools",Context.MODE_PRIVATE);boolean run=p.getBoolean("sw_running",false);long saved=p.getLong("sw_elapsed",0),base=p.getLong("sw_base",SystemClock.elapsedRealtime());long elapsed=run?saved+Math.max(0,SystemClock.elapsedRealtime()-base):saved;if(run){r.setChronometer(R.id.sw_chrono,SystemClock.elapsedRealtime()-elapsed,null,true);r.setViewVisibility(R.id.sw_chrono,android.view.View.VISIBLE);r.setViewVisibility(R.id.sw_static,android.view.View.GONE);}else{r.setTextViewText(R.id.sw_static,WidgetSuite.fmtTimer(elapsed));r.setViewVisibility(R.id.sw_static,android.view.View.VISIBLE);r.setViewVisibility(R.id.sw_chrono,android.view.View.GONE);}r.setTextViewText(R.id.sw_toggle,I18n.tr(c,run?"一時停止":"スタート"));r.setTextViewText(R.id.sw_lap_reset,I18n.tr(c,run?"ラップ":"リセット"));r.setOnClickPendingIntent(R.id.sw_toggle,WidgetSuite.action(c,WidgetActionReceiver.SW_TOGGLE,0,27000+id));r.setOnClickPendingIntent(R.id.sw_lap_reset,WidgetSuite.action(c,WidgetActionReceiver.SW_LAP_RESET,0,27100+id));r.setOnClickPendingIntent(R.id.widget_root,WidgetSuite.open(c,ClockActivity.class,"mode","stopwatch",27200+id));m.updateAppWidget(id,r);}public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,android.os.Bundle b){update(c,m,id);}}
